CREATE TABLE "customers" (
  "customer_id" INTEGER NOT NULL,
  "cust_first_name" VARCHAR(20) NOT NULL,
  "cust_last_name" VARCHAR(20) NOT NULL,
  "cust_street_address" VARCHAR(40),
  "cust_postal_code" VARCHAR(10),
  "cust_city" VARCHAR(30),
  "cust_state_province" VARCHAR(10),
  "cust_country_id" CHAR(2),
  "nls_language" VARCHAR(3),
  "nls_territory" VARCHAR(30),
  "credit_limit" DECIMAL(9,2),
  "cust_email" VARCHAR(40),
  "account_mgr_id" INTEGER,
  "geo_longitude" DECIMAL(9,6),
  "geo_latitude" DECIMAL(9,6),
  "date_of_birth" DATE,
  "marital_status" VARCHAR(20),
  "gender" VARCHAR(1),
  "income_level" VARCHAR(20),
  PRIMARY KEY ("customer_id"),
  CONSTRAINT "customer_credit_limit_max" CHECK (("credit_limit" <= 5000)),
  CONSTRAINT "customer_id_min" CHECK (("customer_id" > 0))
);

CREATE TABLE "customer_phone_numbers" (
  "customer_id" INTEGER NOT NULL,
  "phone_seq" TINYINT NOT NULL,
  "phone_number" VARCHAR(25) NOT NULL,
  PRIMARY KEY ("customer_id", "phone_seq"),
  CONSTRAINT "cust_phone_customer_fk" FOREIGN KEY ("customer_id") REFERENCES "customers" ("customer_id") ON UPDATE NO ACTION ON DELETE CASCADE
);

CREATE TABLE "product_information" (
  "product_id" INTEGER NOT NULL,
  "product_name" VARCHAR(50),
  "product_description" VARCHAR(2000),
  "category_id" SMALLINT,
  "weight_class" TINYINT,
  "warranty_months" SMALLINT,
  "supplier_id" INTEGER,
  "product_status" VARCHAR(20),
  "list_price" DECIMAL(8,2),
  "min_price" DECIMAL(8,2),
  "catalog_url" VARCHAR(50),
  PRIMARY KEY ("product_id"),
  CONSTRAINT "product_status_lov" CHECK (("product_status" in ('orderable','planned','under development','obsolete')))
);

CREATE TABLE "warehouses" (
  "warehouse_id" INTEGER NOT NULL,
  "warehouse_name" VARCHAR(35),
  "location_id" SMALLINT,
  "geo_longitude" DECIMAL(9,6),
  "geo_latitude" DECIMAL(9,6),
  "warehouse_spec_xml" TEXT,
  "building" VARCHAR(20),
  "area" INTEGER,
  "docks" INTEGER,
  "dock_type" VARCHAR(20),
  "water_access" VARCHAR(1),
  "rail_access" VARCHAR(1),
  "parking" VARCHAR(10),
  "v_clearance" VARCHAR(10),
  PRIMARY KEY ("warehouse_id")
);

CREATE TABLE "inventories" (
  "product_id" INTEGER NOT NULL,
  "warehouse_id" INTEGER NOT NULL,
  "quantity_on_hand" INTEGER NOT NULL,
  PRIMARY KEY ("product_id", "warehouse_id"),
  CONSTRAINT "inventories_product_id_fk" FOREIGN KEY ("product_id") REFERENCES "product_information" ("product_id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "inventories_warehouses_fk" FOREIGN KEY ("warehouse_id") REFERENCES "warehouses" ("warehouse_id") ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE "orders" (
  "order_id" INTEGER NOT NULL,
  "order_date" DATETIME NOT NULL,
  "order_mode" VARCHAR(8),
  "customer_id" INTEGER NOT NULL,
  "order_status" SMALLINT,
  "order_total" DECIMAL(8,2),
  "sales_rep_id" INTEGER,
  "promotion_id" INTEGER,
  PRIMARY KEY ("order_id"),
  CONSTRAINT "orders_customer_id_fk" FOREIGN KEY ("customer_id") REFERENCES "customers" ("customer_id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "order_mode_lov" CHECK (("order_mode" in ('direct','online'))),
  CONSTRAINT "order_total_min" CHECK (("order_total" >= 0))
);

CREATE TABLE "order_items" (
  "order_id" INTEGER NOT NULL,
  "line_item_id" SMALLINT NOT NULL,
  "product_id" INTEGER NOT NULL,
  "unit_price" DECIMAL(8,2),
  "quantity" INTEGER,
  PRIMARY KEY ("order_id", "line_item_id"),
  CONSTRAINT "order_items_order_id_fk" FOREIGN KEY ("order_id") REFERENCES "orders" ("order_id") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "order_items_product_id_fk" FOREIGN KEY ("product_id") REFERENCES "product_information" ("product_id") ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE "product_descriptions" (
  "product_id" INTEGER NOT NULL,
  "language_id" VARCHAR(3) NOT NULL,
  "translated_name" VARCHAR(50) NOT NULL,
  "translated_description" VARCHAR(2000) NOT NULL,
  PRIMARY KEY ("product_id", "language_id"),
  CONSTRAINT "pd_product_id_fk" FOREIGN KEY ("product_id") REFERENCES "product_information" ("product_id") ON UPDATE NO ACTION ON DELETE NO ACTION
);

CREATE TABLE "promotions" (
  "promo_id" INTEGER NOT NULL,
  "promo_name" VARCHAR(20),
  PRIMARY KEY ("promo_id")
);

